// 錯題複習資料，由 tools/import_mistakes.py 從 review/*.md 產生，勿手改
const MISTAKES = [{"id": "Carol Bai 多益文法 Part 5#Day1-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day1-Q1", "q": "The new employee's ______ is to design a new product component for the company.", "opts": ["assignment", "assigned", "assignee", "assigning"], "ans": 0, "exp": "所有格 employee's 之後、動詞 is 之前需要名詞當主詞，「任務」用 assignment。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day3-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day3-Q1", "q": "The entire team is ______ for the project's outcome.", "opts": ["response", "responsibleness", "responsible", "respond"], "ans": 2, "exp": "be 動詞後接形容詞當主詞補語，responsible（負責的）；response 是名詞、respond 是動詞。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day4-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day4-Q1", "q": "When we discuss the new marketing plan, let's do it ______.", "opts": ["creatively", "creative", "creativity", "creation"], "ans": 0, "exp": "修飾動詞 do 要用副詞 creatively（有創意地）。", "tags": ["詞性", "副詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q1", "q": "The ______ nature of the project makes it challenging to complete on time.", "opts": ["complexity", "complex", "complexify", "complexness"], "ans": 1, "exp": "名詞 nature 前需形容詞修飾，complex（複雜的）。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q2", "q": "Management appreciates employees who ______ new initiatives to improve the company's operations.", "opts": ["proposal", "proposer", "proposing", "propose"], "ans": 3, "exp": "關係代名詞 who 引導的子句需要動詞，先行詞 employees 為複數用原形 propose。", "tags": ["詞性", "動詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q3", "q": "The company's success is directly tied to the ______ of its employees.", "opts": ["product", "productive", "productivity", "production"], "ans": 2, "exp": "冠詞 the 之後、of 之前需要名詞，此處指員工的「生產力」productivity。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day6-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day6-Q1", "q": "My boss usually ______ early on Fridays.", "opts": ["has left", "is leaving", "leaves", "has been leaving"], "ans": 2, "exp": "usually 表習慣，用現在簡單式；主詞第三人稱單數用 leaves。", "tags": ["時態", "現在式"]}, {"id": "Carol Bai 多益文法 Part 5#Day7-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day7-Q1", "q": "We ______ a new supplier last month. Their prices are much better.", "opts": ["had found", "were finding", "found", "had been finding"], "ans": 2, "exp": "last month 是明確的過去時間，用過去簡單式 found。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Day7-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day7-Q2", "q": "Sorry for being late. I ______ some emails before leaving the office.", "opts": ["answered", "was answering", "had answered", "had been answering"], "ans": 0, "exp": "單純敘述過去發生的動作，用過去簡單式 answered。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Day8-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day8-Q1", "q": "How long ______ the presentation before the meeting starts?", "opts": ["will you prepare", "will you be preparing", "will you have prepared", "will you have been preparing"], "ans": 3, "exp": "問到未來某時點（會議開始前）為止「已持續多久」，用未來完成進行式。", "tags": ["時態", "未來式"]}, {"id": "Carol Bai 多益文法 Part 5#Day8-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day8-Q2", "q": "By the time we arrive, they ______ the contract.", "opts": ["will have signed", "will be signing", "will have been signing", "will have been signed"], "ans": 0, "exp": "By the time + 現在式子句，主句用未來完成式，表在到達前已完成。", "tags": ["時態", "未來完成式"]}, {"id": "Carol Bai 多益文法 Part 5#Day9-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day9-Q1", "q": "My team and I ______ a new project proposal tomorrow.", "opts": ["present", "are presenting", "have presented", "have been presenting"], "ans": 1, "exp": "tomorrow 表已安排好的計畫，用現在進行式表未來 are presenting。", "tags": ["時態", "未來式"]}, {"id": "Carol Bai 多益文法 Part 5#Day10-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day10-Q1", "q": "Our competitors launched a new product, and ______ quickly became popular in the market.", "opts": ["it", "they", "them", "their"], "ans": 0, "exp": "指前面單數的 a new product，當主詞用主格 it。", "tags": ["代名詞", "主格"]}, {"id": "Carol Bai 多益文法 Part 5#Day10-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day10-Q2", "q": "The CEO has announced a new policy, and ______ will be implemented starting next month.", "opts": ["they", "it", "them", "their"], "ans": 1, "exp": "指單數的 a new policy，當主詞用主格 it。", "tags": ["代名詞", "主格"]}, {"id": "Carol Bai 多益文法 Part 5#Day11-Q5", "src": "Carol Bai 多益文法 Part 5", "no": "Day11-Q5", "q": "The CEO commended the team for ______ hard work and dedication to the project.", "opts": ["theirs", "it's", "their", "him"], "ans": 2, "exp": "修飾名詞 hard work 需所有格，指複數 the team 用 their。", "tags": ["代名詞", "所有格"]}, {"id": "Carol Bai 多益文法 Part 5#Day11-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day11-Q6", "q": "The sales department is responsible for meeting ______ monthly targets.", "opts": ["its", "it's", "there", "theirs"], "ans": 0, "exp": "所有格修飾 monthly targets，指單數 department 用 its；it's 是 it is 的縮寫。", "tags": ["代名詞", "所有格"]}, {"id": "Carol Bai 多益文法 Part 5#Day12-Q8", "src": "Carol Bai 多益文法 Part 5", "no": "Day12-Q8", "q": "The team members discussed their individual tasks, and ______ were completed on time.", "opts": ["mine", "theirs", "my", "me"], "ans": 1, "exp": "theirs = their tasks，用所有格代名詞代替前面提到的名詞當主詞。", "tags": ["代名詞", "所有格代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day13-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day13-Q12", "q": "The company values its employees and offers ______ various benefits and opportunities for growth.", "opts": ["they", "them", "their", "themselves"], "ans": 1, "exp": "動詞 offers 的受詞，指 employees 用受格 them。", "tags": ["代名詞", "受格"]}, {"id": "Carol Bai 多益文法 Part 5#Day14-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day14-Q16", "q": "As a team, we take ownership of our work. We challenge ______ to be the best in our industry.", "opts": ["oneself", "yourselves", "ourselves", "itself"], "ans": 2, "exp": "主詞 we 與受詞為同一群人，用反身代名詞 ourselves。", "tags": ["代名詞", "反身代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day14-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day14-Q17", "q": "Mary prepared the presentation for the conference ______.", "opts": ["myself", "itself", "herself", "her"], "ans": 2, "exp": "強調 Mary「親自」完成，用反身代名詞 herself。", "tags": ["代名詞", "反身代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day15-Q24", "src": "Carol Bai 多益文法 Part 5", "no": "Day15-Q24", "q": "The new advertising campaign generated more leads than ______ used in the past.", "opts": ["whose", "those", "what", "which"], "ans": 1, "exp": "代替前面複數名詞 leads，用 those（= the leads that were used）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day16-Q30", "src": "Carol Bai 多益文法 Part 5", "no": "Day16-Q30", "q": "The new marketing strategy resulted in a higher conversion rate than ______ of the previous campaigns.", "opts": ["them", "they", "that", "their"], "ans": 2, "exp": "代替單數名詞 conversion rate，用 that 避免重複（than that of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day16-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day16-Q31", "q": "Company XYZ's customer retention rate is higher than ______ of its competitors.", "opts": ["that", "they", "them", "their"], "ans": 0, "exp": "代替單數名詞 rate，用 that（than that of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day17-Q34", "src": "Carol Bai 多益文法 Part 5", "no": "Day17-Q34", "q": "The company's new advertising campaign is targeted at ______ who belongs to the 18-35 age group.", "opts": ["anything", "anyone", "any", "another"], "ans": 1, "exp": "指「任何人」用 anyone，後接 who 引導的形容詞子句。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day17-Q35", "src": "Carol Bai 多益文法 Part 5", "no": "Day17-Q35", "q": "______ interested in attending the conference should register online before the deadline.", "opts": ["Anything", "Another", "Any", "Anyone"], "ans": 3, "exp": "句首當主詞，指「任何有興趣的人」用 Anyone。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day18-Q38", "src": "Carol Bai 多益文法 Part 5", "no": "Day18-Q38", "q": "Despite offering an incentive, ______ signed up for the training session on advanced sales techniques.", "opts": ["nobody", "several", "everybody", "anyone"], "ans": 0, "exp": "儘管提供誘因卻「沒有人」報名，前後語意轉折用 nobody。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day18-Q39", "src": "Carol Bai 多益文法 Part 5", "no": "Day18-Q39", "q": "______ knew about the impending merger between the two companies until the official announcement was made.", "opts": ["Somebody", "Nobody", "Everyone", "Anybody"], "ans": 1, "exp": "直到正式宣布前「沒有人」知道，用 Nobody。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q42", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q42", "q": "In the survey, it was found that ______ clients prefer to communicate via email.", "opts": ["majority", "almost", "most", "the most"], "ans": 2, "exp": "most + 複數名詞 = 大多數的…，most clients；majority 需 the majority of，almost 是副詞。", "tags": ["代名詞", "不定形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q43", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q43", "q": "______ of the participants rated the conference venue as excellent.", "opts": ["Much all", "Most", "Much", "The most"], "ans": 1, "exp": "most of the + 名詞，用 Most；majority 要 the majority of，much 修飾不可數。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q44", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q44", "q": "The sales team discovered that ______ customers are interested in the new product.", "opts": ["majority", "almost", "the most", "most"], "ans": 3, "exp": "most + 複數名詞 customers，表「大多數的」。", "tags": ["代名詞", "不定形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day20-Q47", "src": "Carol Bai 多益文法 Part 5", "no": "Day20-Q47", "q": "______ the economic downturn, the company managed to achieve record sales figures last quarter.", "opts": ["Throughout", "Besides", "Despite", "Versus"], "ans": 2, "exp": "後接名詞片語 the economic downturn，表「儘管」用介系詞 Despite。", "tags": ["介系詞", "despite"]}, {"id": "Carol Bai 多益文法 Part 5#Day20-Q48", "src": "Carol Bai 多益文法 Part 5", "no": "Day20-Q48", "q": "The marketing campaign was successful, ______ the limited budget allocated for it.", "opts": ["beyond", "despite", "throughout", "above"], "ans": 1, "exp": "後接名詞片語表讓步「儘管預算有限」，用 despite。", "tags": ["介系詞", "despite"]}, {"id": "Carol Bai 多益文法 Part 5#Day21-Q54", "src": "Carol Bai 多益文法 Part 5", "no": "Day21-Q54", "q": "All employees must submit their expense reports ______ the end of the month.", "opts": ["between", "before", "beyond", "through"], "ans": 1, "exp": "在月底「之前」提交，用 before。", "tags": ["介系詞", "before"]}, {"id": "Carol Bai 多益文法 Part 5#Day22-Q60", "src": "Carol Bai 多益文法 Part 5", "no": "Day22-Q60", "q": "The company's new product must be launched ______ two months to meet the market demand.", "opts": ["within", "except", "along", "amid"], "ans": 0, "exp": "表「在兩個月之內」用 within。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day22-Q62", "src": "Carol Bai 多益文法 Part 5", "no": "Day22-Q62", "q": "The sales team managed to close the deal ______ a few days of negotiations.", "opts": ["besides", "during", "among", "within"], "ans": 3, "exp": "表在「一段時間之內」完成，用 within a few days。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day23-Q66", "src": "Carol Bai 多益文法 Part 5", "no": "Day23-Q66", "q": "The new marketing campaign is designed ______ increasing brand awareness in the target market.", "opts": ["above", "for", "without", "upon"], "ans": 1, "exp": "be designed for + 動名詞，表目的用 for。", "tags": ["介系詞", "for"]}, {"id": "Carol Bai 多益文法 Part 5#Day23-Q67", "src": "Carol Bai 多益文法 Part 5", "no": "Day23-Q67", "q": "The company has allocated a budget ______ research and development of new products.", "opts": ["since", "for", "on", "behind"], "ans": 1, "exp": "撥預算「用於」研發，用 for。", "tags": ["介系詞", "for"]}, {"id": "Carol Bai 多益文法 Part 5#Day24-Q71", "src": "Carol Bai 多益文法 Part 5", "no": "Day24-Q71", "q": "The marketing team is currently working ______ a new advertising campaign to promote the latest product.", "opts": ["of", "in", "for", "on"], "ans": 3, "exp": "work on「著手進行、致力於」，固定搭配用 on。", "tags": ["介系詞", "on"]}, {"id": "Carol Bai 多益文法 Part 5#Day25-Q77", "src": "Carol Bai 多益文法 Part 5", "no": "Day25-Q77", "q": "The marketing team successfully promoted the new product ______ social media platforms.", "opts": ["unlike", "around", "through", "within"], "ans": 2, "exp": "透過社群平台，表「透過某媒介」用 through。", "tags": ["介系詞", "through"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q82", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q82", "q": "Our company experienced a surge in website traffic ______ the holiday season, thanks to our special promotions.", "opts": ["during", "without", "since", "down"], "ans": 0, "exp": "during + 表期間的名詞（the holiday season），表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q83", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q83", "q": "______ the conference, there will be networking sessions to connect industry professionals.", "opts": ["Under", "Behind", "During", "Across"], "ans": 2, "exp": "During + 名詞，表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day27-Q87", "src": "Carol Bai 多益文法 Part 5", "no": "Day27-Q87", "q": "The strategic partnership aims to enhance collaboration ______ our research and development teams and academic institutions.", "opts": ["through", "beside", "between", "under"], "ans": 2, "exp": "between A and B，兩方之間的合作用 between。", "tags": ["介系詞", "between"]}, {"id": "Carol Bai 多益文法 Part 5#Day28-Q93", "src": "Carol Bai 多益文法 Part 5", "no": "Day28-Q93", "q": "All invoices must be paid ______ the designated due date to avoid any late fees.", "opts": ["on", "by", "within", "through"], "ans": 1, "exp": "在期限前（不遲於）付清，用 by。", "tags": ["介系詞", "by"]}, {"id": "Carol Bai 多益文法 Part 5#Day29-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day29-Q1", "q": "______ market research, the new product has a high potential for success.", "opts": ["According to", "In case of", "Without", "Opposite to"], "ans": 0, "exp": "根據市場調查，用 According to。", "tags": ["介系詞", "according to"]}, {"id": "Carol Bai 多益文法 Part 5#Day29-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day29-Q3", "q": "All project expenses must be managed ______ established budget guidelines.", "opts": ["in favor of", "in accordance with", "in front of", "in order that"], "ans": 1, "exp": "依照既定規範，用 in accordance with（依照…）。", "tags": ["介系詞", "in accordance with"]}, {"id": "Carol Bai 多益文法 Part 5#Day30-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day30-Q6", "q": "The conference attendees will not be granted access to the seminar room ______ a valid registration badge.", "opts": ["considering", "with", "through", "without"], "ans": 3, "exp": "沒有有效證件就不得進入，用 without。", "tags": ["介系詞", "without"]}, {"id": "Carol Bai 多益文法 Part 5#Day30-Q7", "src": "Carol Bai 多益文法 Part 5", "no": "Day30-Q7", "q": "The company cannot finalize the contract ______ the client's signature.", "opts": ["below", "above", "without", "across"], "ans": 2, "exp": "沒有客戶簽名就無法定案，用 without。", "tags": ["介系詞", "without"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q11", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q11", "q": "The vendor requires payment to be made ______ the delivery of the goods.", "opts": ["because of", "prior to", "due to", "apart from"], "ans": 1, "exp": "在交貨「之前」付款，用 prior to（= before）。", "tags": ["介系詞", "prior to"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q12", "q": "The team needs to complete the project plan ______ the client presentation.", "opts": ["prior to", "along with", "regardless of", "as for"], "ans": 0, "exp": "在客戶簡報「之前」完成，用 prior to。", "tags": ["介系詞", "prior to"]}, {"id": "Carol Bai 多益文法 Part 5#Day32-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day32-Q16", "q": "In order to achieve sustainable growth, our company must look for opportunities that go ______ our current market reach.", "opts": ["beyond", "within", "through", "beneath"], "ans": 0, "exp": "go beyond「超越」既有市場範圍。", "tags": ["介系詞", "beyond"]}, {"id": "Carol Bai 多益文法 Part 5#Day32-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day32-Q17", "q": "All items are currently on sale for 20% off ______ the new arrivals in the \"Latest Trends\" section.", "opts": ["alongside", "throughout", "except", "beneath"], "ans": 2, "exp": "除了新品「之外」皆打折，用 except。", "tags": ["介系詞", "except"]}, {"id": "Carol Bai 多益文法 Part 5#Day33-Q21", "src": "Carol Bai 多益文法 Part 5", "no": "Day33-Q21", "q": "The marketing presentation has been rescheduled and will take place on Friday, ______ Thursday.", "opts": ["therefore", "but", "since", "instead of"], "ans": 3, "exp": "改到週五「而非」週四，用 instead of。", "tags": ["介系詞", "instead of"]}, {"id": "Carol Bai 多益文法 Part 5#Day33-Q22", "src": "Carol Bai 多益文法 Part 5", "no": "Day33-Q22", "q": "The new software interface is intuitive and user-friendly, ______ the previous version which was complex and hard to navigate.", "opts": ["unlike", "alongside", "within", "beyond"], "ans": 0, "exp": "與舊版「不同」，用 unlike。", "tags": ["介系詞", "unlike"]}, {"id": "Carol Bai 多益文法 Part 5#Day34-Q26", "src": "Carol Bai 多益文法 Part 5", "no": "Day34-Q26", "q": "The workshop on effective communication skills is conducted by experts ______ the renowned Communication Excellence Institute.", "opts": ["by", "from", "within", "into"], "ans": 1, "exp": "來自某機構的專家，表來源用 from。", "tags": ["介系詞", "from"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q31", "q": "The manager should meet with the team ______ discussing the new project.", "opts": ["back to", "when", "between", "in part"], "ans": 1, "exp": "when + V-ing，表「在…的時候」when discussing。", "tags": ["介系詞", "when"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q33", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q33", "q": "The new advertising campaign aims to make our product stand ______ among competitors in the market.", "opts": ["with", "against", "through", "out"], "ans": 3, "exp": "stand out「脫穎而出」，片語動詞用 out。", "tags": ["片語", "stand out"]}, {"id": "Carol Bai 多益文法 Part 5#Day37-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day37-Q1", "q": "All project proposals must be submitted ______ two weeks from today's date.", "opts": ["among", "within", "unless", "while"], "ans": 1, "exp": "在兩週「之內」提交，用 within。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day37-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day37-Q2", "q": "______ the contract, the project should be completed within six months.", "opts": ["Apart from", "Instead of", "According to", "Due to"], "ans": 2, "exp": "根據合約規定，用 According to。", "tags": ["介系詞", "according to"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q1", "q": "______ he is negotiating with other companies, Henry intends to stay with our organization.", "opts": ["Prior to", "From", "Although", "Perhaps"], "ans": 2, "exp": "後接完整子句表讓步「雖然」，用連接詞 Although；Prior to/From 是介系詞。", "tags": ["連接詞", "although"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q2", "q": "______ the market research was thorough, the product launch failed to meet expectations.", "opts": ["Although", "Conversely", "Nevertheless", "Accordingly"], "ans": 0, "exp": "雖然市調徹底，結果仍失敗，用讓步連接詞 Although；其餘為副詞。", "tags": ["連接詞", "although"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q3", "q": "The company is willing to consider applicants for the management position ______ they lack a formal degree.", "opts": ["except for", "even if", "along with", "in spite of"], "ans": 1, "exp": "後接子句表「即使」，用連接詞 even if；in spite of / except for 後接名詞。", "tags": ["連接詞", "even if"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q6", "q": "______ Emily excels in marketing, her colleague Jack specializes in market research.", "opts": ["In case", "As if", "While", "Whether"], "ans": 2, "exp": "對比兩人專長，用 While（然而、相對地）。", "tags": ["連接詞", "while"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q7", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q7", "q": "______ the sales team focuses on international markets, the marketing team concentrates on domestic strategies.", "opts": ["Only if", "In case", "When", "While"], "ans": 3, "exp": "對比兩個團隊的重點，用 While。", "tags": ["連接詞", "while"]}, {"id": "Carol Bai 多益文法 Part 5#Day40-Q11", "src": "Carol Bai 多益文法 Part 5", "no": "Day40-Q11", "q": "The presentation was rescheduled to next Tuesday ______ that the team could finalize the sales figures.", "opts": ["however", "when", "rather", "so"], "ans": 3, "exp": "so that 引導目的子句「以便」，此處空格填 so。", "tags": ["連接詞", "so that"]}, {"id": "Carol Bai 多益文法 Part 5#Day40-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day40-Q12", "q": "Please complete the financial report by Friday afternoon ______ the audit team can review it over the weekend.", "opts": ["so that", "in order to", "that is", "in case of"], "ans": 0, "exp": "後接完整子句表目的，用 so that；in order to 後接原形動詞。", "tags": ["連接詞", "so that"]}, {"id": "Carol Bai 多益文法 Part 5#Day41-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day41-Q16", "q": "Robert Garrison has been the company's legal counsel ______ it was established.", "opts": ["ever", "before", "since", "nonetheless"], "ans": 2, "exp": "現在完成式 + since + 子句，表「自從…以來」。", "tags": ["連接詞", "since"]}, {"id": "Carol Bai 多益文法 Part 5#Day41-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day41-Q17", "q": "______ the recent merger, we now have openings for several key positions.", "opts": ["Beneath", "Since", "Until", "Despite"], "ans": 1, "exp": "由於近期合併（表原因），用 Since。", "tags": ["連接詞", "since"]}, {"id": "Carol Bai 多益文法 Part 5#Day42-Q21", "src": "Carol Bai 多益文法 Part 5", "no": "Day42-Q21", "q": "______ the conference call, Mr. Johnson will provide updates on the project.", "opts": ["After", "Now", "Soon", "Next"], "ans": 0, "exp": "電話會議「之後」提供最新進度，用 After。", "tags": ["連接詞", "after"]}, {"id": "Carol Bai 多益文法 Part 5#Day43-Q27", "src": "Carol Bai 多益文法 Part 5", "no": "Day43-Q27", "q": "The company is planning to expand its operations to China, ______ it is still facing some challenges.", "opts": ["despite", "or", "but", "either"], "ans": 2, "exp": "前後語意轉折，用對等連接詞 but。", "tags": ["連接詞", "but"]}, {"id": "Carol Bai 多益文法 Part 5#Day44-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day44-Q31", "q": "This seminar is designed for entrepreneurs ______ executives seeking innovative strategies.", "opts": ["nevertheless", "rather", "as well as", "albeit"], "ans": 2, "exp": "連接兩個並列名詞 entrepreneurs 與 executives，用 as well as。", "tags": ["連接詞", "as well as"]}, {"id": "Carol Bai 多益文法 Part 5#Day44-Q32", "src": "Carol Bai 多益文法 Part 5", "no": "Day44-Q32", "q": "The training program caters to entry-level employees ______ mid-level managers eager to enhance their skills.", "opts": ["as well as", "while", "therefore", "similarly"], "ans": 0, "exp": "連接兩類並列對象，用 as well as（以及）。", "tags": ["連接詞", "as well as"]}, {"id": "Carol Bai 多益文法 Part 5#Day45-Q37", "src": "Carol Bai 多益文法 Part 5", "no": "Day45-Q37", "q": "______ a customer fails to provide a valid purchase receipt, the return process cannot be initiated.", "opts": ["Except", "So", "That", "If"], "ans": 3, "exp": "條件句「如果…就無法…」，用 If。", "tags": ["連接詞", "if"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q41", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q41", "q": "Corporate reports must be submitted to the board ______ the financial quarter concludes.", "opts": ["once", "soon", "often", "usually"], "ans": 0, "exp": "once 當連接詞引導時間子句「一旦…就」；soon/often/usually 是副詞。", "tags": ["連接詞", "once"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q42", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q42", "q": "The project manager will finalize the budget ______ the financial analysis is complete.", "opts": ["overall", "due to", "once", "soon"], "ans": 2, "exp": "once 引導時間子句「一旦…完成」；due to 後接名詞、overall/soon 為副詞。", "tags": ["連接詞", "once"]}, {"id": "Carol Bai 多益文法 Part 5#Day1-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day1-Q2", "q": "The deadline for submitting the project analysis is next Friday. Please make sure to meet the ______.", "opts": ["datable", "dating", "deadline", "deadliness"], "ans": 2, "exp": "meet the deadline「趕上截止期限」，空格需名詞 deadline。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day2-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day2-Q1", "q": "If you want to ______ your claim, you need to provide more evidence.", "opts": ["substantiate", "substantial", "substance", "substantially"], "ans": 0, "exp": "受詞 your claim 前需動詞，substantiate「證實、證明」；substantial 形容詞、substance 名詞。", "tags": ["詞性", "動詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day3-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day3-Q2", "q": "Our sales team needs to be ______ in their approach to customers to increase satisfaction.", "opts": ["proactive", "proactivity", "proactiveness", "proactively"], "ans": 0, "exp": "be 動詞後接形容詞當補語，proactive「積極主動的」。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day4-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day4-Q2", "q": "Our company holds meetings ______ to ensure that everyone is well informed.", "opts": ["regularity", "regularly", "regular", "regulate"], "ans": 1, "exp": "修飾動詞 holds 用副詞 regularly「定期地」。", "tags": ["詞性", "副詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day13-Q13", "src": "Carol Bai 多益文法 Part 5", "no": "Day13-Q13", "q": "The company provided ______ with a comprehensive training program to enhance their skills.", "opts": ["they", "their", "them", "themselves"], "ans": 2, "exp": "provide sb with sth，動詞的受詞用受格 them。", "tags": ["代名詞", "受格"]}, {"id": "Carol Bai 多益文法 Part 5#Day15-Q23", "src": "Carol Bai 多益文法 Part 5", "no": "Day15-Q23", "q": "Our company's customer satisfaction ratings are higher than ______ of our main rivals.", "opts": ["which", "whose", "what", "those"], "ans": 3, "exp": "代替前面複數名詞 ratings，用 those（than those of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day21-Q55", "src": "Carol Bai 多益文法 Part 5", "no": "Day21-Q55", "q": "The marketing team needs to finalize the campaign strategy ______ the budget meeting.", "opts": ["unlike", "without", "before", "within"], "ans": 2, "exp": "在預算會議「之前」敲定策略，用 before。", "tags": ["介系詞", "before"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q84", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q84", "q": "Please be advised that the office will be closed ______ the weekend for renovations.", "opts": ["under", "alongside", "about", "during"], "ans": 3, "exp": "during + 期間名詞 the weekend，表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q13", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q13", "q": "Please submit your expense reports ______ attending the company training seminar.", "opts": ["although", "underneath", "after", "throughout"], "ans": 2, "exp": "after + V-ing，表「在…之後」after attending。", "tags": ["介系詞", "after"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q32", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q32", "q": "The seminar will be targeted ______ improving leadership skills for middle and upper management.", "opts": ["for", "in", "at", "with"], "ans": 2, "exp": "be targeted at「以…為目標、針對」。", "tags": ["介系詞", "at"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q8", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q8", "q": "______ the shipment was delayed, the team completed the project on time.", "opts": ["Even though", "Instead of", "In addition to", "On top of"], "ans": 0, "exp": "後接完整子句表讓步「儘管」，用連接詞 Even though；其餘後接名詞。", "tags": ["連接詞", "even though"]}, {"id": "Carol Bai 多益文法 Part 5#Day43-Q26", "src": "Carol Bai 多益文法 Part 5", "no": "Day43-Q26", "q": "The company's new policy allows employees to work from home ______ come to the office.", "opts": ["and", "or", "with", "since"], "ans": 1, "exp": "在家或到辦公室，二擇一用對等連接詞 or。", "tags": ["連接詞", "or"]}, {"id": "Carol Bai 多益文法 Part 5#Day45-Q36", "src": "Carol Bai 多益文法 Part 5", "no": "Day45-Q36", "q": "ABC Consulting Firm provides a 5 percent discount ______ clients complete their payment within 15 days.", "opts": ["also", "but", "if", "yet"], "ans": 2, "exp": "條件句「如果…就給折扣」，用連接詞 if。", "tags": ["連接詞", "if"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q43", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q43", "q": "______ the necessary permits are obtained, the construction project cannot commence.", "opts": ["Mostly", "At least", "No more", "Unless"], "ans": 3, "exp": "unless「除非」引導條件，除非取得許可否則不能動工。", "tags": ["連接詞", "unless"]}, {"id": "Carol Bai 多益文法 Part 5#Extra-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Extra-Q1", "q": "The marketing team ______ a new strategy to increase brand awareness last quarter.", "opts": ["develop", "developed", "was developing", "develops"], "ans": 1, "exp": "last quarter 為明確過去時間，用過去簡單式 developed。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Extra-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Extra-Q2", "q": "The annual report ______ by the accounting department before the board meeting.", "opts": ["prepare", "prepared", "was prepared", "prepares"], "ans": 2, "exp": "報告是「被」準備的，用被動語態；配合過去時間用 was prepared。", "tags": ["語態", "被動"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day7-Q3", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day7-Q3", "q": "Ms. Garcia will set ______ on her business trip to Singapore early tomorrow morning.", "opts": ["up", "out", "aside", "off"], "ans": 3, "exp": "set off「出發、動身」；set up 設立、set aside 撥出、set out 著手（也可指出發，但搭配 on a trip 慣用 set off）。", "tags": ["片語動詞", "set"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day8-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day8-Q1", "q": "At the sales meeting, the manager urged the team to go ______ the biggest contract.", "opts": ["over", "for", "with", "through"], "ans": 1, "exp": "go for「爭取、努力追求」；go over 檢查、go through 經歷、go with 搭配。", "tags": ["片語動詞", "go"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day8-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day8-Q2", "q": "The legal team must go ______ every clause of the contract carefully before the CEO signs it.", "opts": ["over", "for", "with", "through"], "ans": 0, "exp": "go over「仔細檢查、逐一審視」每個條款。", "tags": ["片語動詞", "go"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q1", "q": "The contract was signed ______ both parties after the negotiation.", "opts": ["for", "with", "by", "on"], "ans": 2, "exp": "被動語態 be signed by sb，表「由…簽署」。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q2", "q": "The new policy will be implemented ______ departments starting next month.", "opts": ["to", "by", "on", "across"], "ans": 3, "exp": "across departments「跨各部門」，表遍及範圍。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q3", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q3", "q": "The CEO expressed gratitude ______ the employees for their hard work.", "opts": ["to", "with", "on", "by"], "ans": 0, "exp": "express gratitude to sb「向某人表達感謝」。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day2-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day2-Q1", "q": "The manager was impressed with her resume and decided to schedule ______ immediately.", "opts": ["a resume", "an interview", "an offer", "a contract"], "ans": 1, "exp": "對履歷印象深刻，接著安排「面試」an interview。", "tags": ["字彙", "徵才"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day4-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day4-Q1", "q": "Our company will launch a new advertising ______ next month to promote our products.", "opts": ["campaign", "survey", "advertisement", "brochure"], "ans": 0, "exp": "advertising campaign「廣告活動」為固定搭配。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day5-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day5-Q1", "q": "You should make a hotel ______ at least two weeks before your business trip.", "opts": ["reservation", "confirmation", "expense", "itinerary"], "ans": 0, "exp": "make a reservation「預訂」，hotel reservation 訂房。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day6-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day6-Q1", "q": "You can use your credit card to make ______ on our secure website.", "opts": ["a purchase", "a refund", "a receipt", "a coupon"], "ans": 0, "exp": "make a purchase「進行購買」。", "tags": ["字彙", "購物"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day7-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day7-Q1", "q": "Before heading to the airport, it is important to confirm your ______ online.", "opts": ["flight", "boarding pass", "baggage", "destination"], "ans": 0, "exp": "出發前線上「確認航班」confirm your flight（線上報到）。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day8-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day8-Q1", "q": "The finance department is working hard to prepare the annual ______ for the next fiscal year.", "opts": ["budget", "expense", "fund", "investment"], "ans": 0, "exp": "annual budget「年度預算」。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day10-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day10-Q1", "q": "To enter the new market, our team must develop an effective ______.", "opts": ["strategy", "objective", "resource", "progress"], "ans": 0, "exp": "develop a strategy「制定策略」。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day10-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day10-Q2", "q": "With this new plan, we hope to achieve our main ______ of increasing market share.", "opts": ["strategy", "objective", "resource", "progress"], "ans": 1, "exp": "objective「目標」，achieve an objective 達成目標。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day11-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day11-Q1", "q": "Both parties must sign the ______ before the agreement is official.", "opts": ["lease", "property", "facility", "location"], "ans": 0, "exp": "sign the lease「簽署租約」；property/facility/location 均非可簽署文件。", "tags": ["字彙", "租賃"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day12-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day12-Q1", "q": "The management has decided to implement a new ______ regarding work-from-home arrangements.", "opts": ["policy", "guideline", "regulation", "schedule"], "ans": 0, "exp": "implement a new policy「實施新政策」，管理層針對制度多用 policy。", "tags": ["字彙", "管理"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day13-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day13-Q1", "q": "After reviewing over 100 applications, we will shortlist the top five ______ for an interview.", "opts": ["candidate", "qualification", "reference", "experience"], "ans": 0, "exp": "候選人 candidate；shortlist candidates 列入面試名單。", "tags": ["字彙", "徵才"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day14-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day14-Q1", "q": "For popular restaurants, it is always a good idea to book ______ in advance.", "opts": ["a table", "a special", "an order", "a check"], "ans": 0, "exp": "book a table「訂位」。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day15-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day15-Q1", "q": "To ensure the meeting is productive, we must set a clear ______ beforehand.", "opts": ["agenda", "venue", "registration", "schedule"], "ans": 0, "exp": "agenda「議程」，set an agenda 訂定會議議程。", "tags": ["字彙", "會議"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day16-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day16-Q1", "q": "To better manage his finances, Mr. Smith decided to open a new savings ______ at the local bank.", "opts": ["account", "loan", "deposit", "transaction"], "ans": 0, "exp": "savings account「儲蓄帳戶」，open an account 開戶。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day19-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day19-Q1", "q": "The museum is proud to display its newest ______: a restored 18th-century carriage.", "opts": ["exhibit", "admission", "artifact", "collection"], "ans": 0, "exp": "博物館展出的「展品」用 exhibit；admission 是入場費。", "tags": ["字彙", "藝文"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day21-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day21-Q1", "q": "The receptionist helped me schedule ______ for my next dental check-up in six months.", "opts": ["an appointment", "a cavity", "an X-ray", "a cleaning"], "ans": 0, "exp": "schedule an appointment「預約」。", "tags": ["字彙", "醫療"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day22-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day22-Q2", "q": "Since neither side would agree completely, they decided to reach ______ by meeting in the middle.", "opts": ["a deal", "a compromise", "terms", "a counteroffer"], "ans": 1, "exp": "reach a compromise「達成妥協」，各退一步。", "tags": ["字彙", "談判"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day24-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day24-Q1", "q": "Before submitting the report, please edit the ______ carefully to check for any spelling errors.", "opts": ["document", "file", "copy", "text"], "ans": 0, "exp": "edit the document「編修文件」，校對拼字錯誤。", "tags": ["字彙", "文書"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day32-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day32-Q1", "q": "Before mass production, the R&D team must first develop a functional ______ for testing.", "opts": ["prototype", "feedback", "requirement", "product"], "ans": 0, "exp": "prototype「原型、雛型」，量產前先做原型測試。", "tags": ["字彙", "研發"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day35-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day35-Q1", "q": "The machine stopped working, so we had to call a specialist to replace a faulty electronic ______.", "opts": ["component", "malfunction", "manual", "technician"], "ans": 0, "exp": "electronic component「電子零件」，更換故障零件。", "tags": ["字彙", "技術"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day37-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day37-Q1", "q": "Because of her outstanding performance, Ms. Lin expects to receive ______ at the end of the year.", "opts": ["a raise", "benefits", "a deduction", "a pension"], "ans": 0, "exp": "a raise「加薪」，表現優異年底期待加薪。", "tags": ["字彙", "職場"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day43-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day43-Q1", "q": "All citizens are required to declare their annual ______ to the tax authorities.", "opts": ["income", "refund", "deadline", "audit"], "ans": 0, "exp": "declare income「申報收入」。", "tags": ["字彙", "稅務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day43-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day43-Q2", "q": "If you have overpaid your taxes, you will be eligible to receive ______ from the government.", "opts": ["an income", "a refund", "a deadline", "an audit"], "ans": 1, "exp": "溢繳稅款可獲「退稅」a refund。", "tags": ["字彙", "稅務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day44-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day44-Q1", "q": "To develop a successful business plan, a new company must first identify its main ______.", "opts": ["competitor", "market share", "weakness", "trend"], "ans": 0, "exp": "identify its main competitor「找出主要競爭對手」。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day45-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day45-Q2", "q": "If the supplier is not willing to lower the ______, we will have to consider other options.", "opts": ["discount", "price", "budget", "offer"], "ans": 1, "exp": "lower the price「降價」，供應商不肯降價就另尋選擇。", "tags": ["字彙", "採購"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day46-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day46-Q1", "q": "To give customers peace of mind, all our electronic devices offer a two-year limited ______.", "opts": ["warranty", "return", "exchange", "checkout"], "ans": 0, "exp": "warranty「保固」，two-year limited warranty 兩年有限保固。", "tags": ["字彙", "售後"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day49-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day49-Q2", "q": "Every salesperson is expected to meet their monthly sales ______ to be eligible for a bonus.", "opts": ["figures", "quota", "pitch", "commission"], "ans": 1, "exp": "sales quota「銷售配額、業績目標」，達標才能領獎金。", "tags": ["字彙", "業務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day50-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day50-Q2", "q": "Due to a critical safety concern, the plant manager made the decision to halt ______ immediately.", "opts": ["component", "production", "assembly line", "output"], "ans": 1, "exp": "halt production「停止生產」。", "tags": ["字彙", "製造"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day51-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day51-Q1", "q": "The legal department has been asked to draft a new employment ______ for all incoming staff.", "opts": ["contract", "obligation", "clause", "agreement"], "ans": 0, "exp": "employment contract「僱傭合約」，draft a contract 擬合約。", "tags": ["字彙", "法務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day51-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day51-Q2", "q": "Both parties are legally bound to fulfill their ______ as stated in the signed document.", "opts": ["contract", "obligation", "clause", "agreement"], "ans": 1, "exp": "fulfill their obligations「履行義務」。", "tags": ["字彙", "法務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day52-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day52-Q1", "q": "Our accounting department will issue ______ to the customer as soon as the order is shipped.", "opts": ["an invoice", "an account", "a fee", "a charge"], "ans": 0, "exp": "issue an invoice「開立發票／帳單」。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day52-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day52-Q2", "q": "We kindly request that you settle your outstanding ______ by the end of the month.", "opts": ["invoice", "account", "fee", "charge"], "ans": 1, "exp": "settle your account「結清帳款」，outstanding account 未結帳款。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day54-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day54-Q1", "q": "I need to go online to book ______ for my business trip to Singapore next month.", "opts": ["a flight", "a seat", "a fare", "an itinerary"], "ans": 0, "exp": "book a flight「訂機票」。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day54-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day54-Q2", "q": "After confirming your booking, you will be prompted to select your preferred ______ on the aircraft.", "opts": ["flight", "seat", "fare", "itinerary"], "ans": 1, "exp": "select your preferred seat「選擇偏好座位」。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day55-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day55-Q1", "q": "To begin our meal, we decided to order a fresh salad as ______.", "opts": ["an appetizer", "a main course", "a beverage", "an ingredient"], "ans": 0, "exp": "appetizer「開胃菜、前菜」，用來開場。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day55-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day55-Q2", "q": "For your ______, you can choose either the grilled salmon or the roasted chicken.", "opts": ["appetizer", "main course", "beverage", "ingredient"], "ans": 1, "exp": "主餐 main course，鮭魚或雞肉二選一。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day56-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day56-Q1", "q": "The administrative assistant's first task each morning is to sort the incoming ______.", "opts": ["mail", "document", "file", "message"], "ans": 0, "exp": "incoming mail「進來的信件」，整理郵件。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day56-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day56-Q2", "q": "For security reasons, you must shred any ______ that contains sensitive company information.", "opts": ["mail", "document", "file", "message"], "ans": 1, "exp": "shred a document「碎掉文件」，銷毀含機密資訊的文件。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day57-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day57-Q1", "q": "Before you attempt to purchase, it is best to check the ______ of the seats online.", "opts": ["availability", "booking", "voucher", "barcode"], "ans": 0, "exp": "check the availability「查看有無空位」。", "tags": ["字彙", "購票"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day57-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day57-Q2", "q": "You will receive an email shortly to confirm your ______ for the concert.", "opts": ["availability", "booking", "voucher", "barcode"], "ans": 1, "exp": "confirm your booking「確認訂位／訂票」。", "tags": ["字彙", "購票"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day58-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day58-Q1", "q": "The popular rock band has announced that they will release their new ______ this fall.", "opts": ["album", "instrument", "melody", "orchestra"], "ans": 0, "exp": "release an album「發行專輯」。", "tags": ["字彙", "音樂"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day58-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day58-Q2", "q": "She is a gifted musician who can play several different types of musical ______.", "opts": ["album", "instrument", "melody", "orchestra"], "ans": 1, "exp": "musical instrument「樂器」。", "tags": ["字彙", "音樂"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day59-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day59-Q2", "q": "Due to the original film's huge success, the studio decided to direct ______.", "opts": ["an actor", "a sequel", "a blockbuster", "an award"], "ans": 1, "exp": "sequel「續集」，原片成功後拍續集。", "tags": ["字彙", "影視"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day60-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day60-Q1", "q": "If you are feeling unwell, you have the right to take a sick ______.", "opts": ["leave", "absence", "time clock", "timesheet"], "ans": 0, "exp": "sick leave「病假」，take a sick leave 請病假。", "tags": ["字彙", "職場"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day61-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day61-Q1", "q": "The event planner will call a meeting tomorrow to finalize the ______ for the three-day workshop.", "opts": ["schedule", "transportation", "accommodation", "details"], "ans": 0, "exp": "finalize the schedule「敲定議程／時程」。", "tags": ["字彙", "活動"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day65-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day65-Q2", "q": "The manager will ______ a memo to inform all employees about the new company policy.", "opts": ["organize", "circulate", "handle", "approve"], "ans": 1, "exp": "circulate a memo「發布、傳閱通知」。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day66-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day66-Q1", "q": "This new advertising campaign is specifically designed to ______ a younger audience.", "opts": ["target", "promote", "generate", "measure"], "ans": 0, "exp": "target an audience「鎖定客群」。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day66-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day66-Q2", "q": "The company plans to use social media influencers to ______ its new line of clothing.", "opts": ["target", "promote", "generate", "measure"], "ans": 1, "exp": "promote「推廣、宣傳」新產品線。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day67-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day67-Q1", "q": "After graduating, they decided to ______ on a journey through Southeast Asia.", "opts": ["embark", "explore", "extend", "cancel"], "ans": 0, "exp": "embark on「展開、著手」，embark on a journey 踏上旅程。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day67-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day67-Q2", "q": "The best way to get to know a new place is to ______ the city and visit its local markets.", "opts": ["embark", "explore", "extend", "cancel"], "ans": 1, "exp": "explore the city「探索城市」。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day68-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day68-Q1", "q": "I wasn't looking for anything specific; I was ______ through the bookstore for an hour.", "opts": ["browsing", "purchasing", "redeeming", "comparing"], "ans": 0, "exp": "browse「隨意瀏覽」，沒有特定目標地逛。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day68-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day68-Q2", "q": "Once you are ready to ______ an item, please proceed to the checkout counter.", "opts": ["browse", "purchase", "redeem", "compare"], "ans": 1, "exp": "purchase「購買」，準備結帳。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第一回合#Q106", "src": "國學閱讀綠本 第一回合", "no": "Q106", "q": "**\\_\\_** workers find in the concert hall will remain in the lost and found center for only one week.", "opts": ["Few", "Several", "Anything", "Most"], "ans": 2, "exp": "句意是在【音樂廳發現的任何東西，只會在失物招領中心保留一周】，所以答案是不定代名詞(C) Anything(任何東西)。代名詞(A)、(B)、(D)分別表示【(許多東西中的)少數/幾個/大部分】，不符合句子要表達的意思。", "tags": ["代名詞", "不定代名詞"]}, {"id": "國學閱讀綠本 第一回合#Q118", "src": "國學閱讀綠本 第一回合", "no": "Q118", "q": "The company shifted **\\_\\_** from its old business model to a fully digital one.", "opts": ["radicalizing", "radically", "radicalize", "radical"], "ans": 1, "exp": "只有副詞能修飾空格前面的動詞(shifted)，所以答案是副詞(B) radically (激進地)。現在分詞(A)，動詞(C)、名詞或形容詞(D)不能修飾動詞。", "tags": ["詞性", "副詞"]}, {"id": "國學閱讀綠本 第一回合#Q125", "src": "國學閱讀綠本 第一回合", "no": "Q125", "q": "Member of the loyalty program may take advantage of discount offers **\\_\\_** earn points for their purchases.", "opts": ["in case", "so that", "regarding", "as well as"], "ans": 3, "exp": "可以將助動詞 (may) 後面的動詞原型 (take advantage of )和動詞原型 (earn) 對等連接，而且能表示【會員除了獲得購物的點數以外，也可以利用折扣優惠】的是B as well as A (除了A還有B)，所以相關連接詞(D) as well as 是正確答案。副詞子句連接詞(A)和(B)後面要接有主詞和動詞的子句，但空格後面缺少主詞，所以這兩個選項不會是正確答案。介系詞(C)後面要接名詞。", "tags": ["連接詞", "as well as"]}, {"id": "國學閱讀綠本 第一回合#Q127", "src": "國學閱讀綠本 第一回合", "no": "Q127", "q": "**\\_\\_** all the cities that the pop singer visited during her recent world tour, Seoul was her favorite.", "opts": ["Of", "About", "To", "Upon"], "ans": 0, "exp": "句意是在造訪所有城市中，首爾是她的最愛，所以介系詞(A) Of (...之中的) 是正確答案。(B) About 表示【關於...】。(C) To 表示方向【往...】。(D) Upon 表示位置或時間點 【在...之上，...之後】", "tags": ["介系詞", "Of"]}, {"id": "國學閱讀綠本 第二回合#Q101", "src": "國學閱讀綠本 第二回合", "no": "Q101", "q": "The interns will work **\\_\\_** the direction of the research department manager.", "opts": ["beyond", "among", "under", "beside"], "ans": 2, "exp": "句意是「實習生將在研究部門經理的指導下工作」，主要考驗介系詞的慣用搭配。在英文中，「under the direction of...」是一個非常常見的固定片語，意思是「在⋯⋯的指導、監督或管理之下」，這裡的 under 帶有從屬或受某人領導的語意。選項 (A) beyond（超越）、(B) among（在⋯⋯之中）以及 (D) beside（在⋯⋯旁邊）在語意邏輯上都無法與 direction（指導）搭配來表示職場上的管理或帶領關係，因此 (C) 是最符合句意與文法的唯一選擇。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第二回合#Q103", "src": "國學閱讀綠本 第二回合", "no": "Q103", "q": "The directors of PenTex are meeting with executives from DRW Corporation, which **\\_\\_** have talked about merging with.", "opts": ["them", "themselves", "their", "they"], "ans": 3, "exp": "句意是「PenTex 的董事們正與 DRW 公司的各高層主管開會，他們曾經討論過要與該公司合併。」在這個句子中，逗號後面的 \"which \\_\\_ have talked about merging with\" 是一個非限定關係子句，當中的 which 作為關係代名詞，代替前面提到的 DRW Corporation。而在這個關係子句裡，\"have talked\" 是動詞片語，因此空格處需要填入一個主格代名詞來作為子句的主詞。根據上下文邏輯，討論合併的主體是前面提過的「PenTex 的董事們（The directors）」，因為是複數名詞，所以必須使用複數的主格代名詞(D) they 來代替。選項 (A) them 是受格，(B) themselves 是反身代名詞，(C) their 是所有格，這三者在文法上都不能直接放在動詞前當作主詞。", "tags": ["代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q109", "src": "國學閱讀綠本 第二回合", "no": "Q109", "q": "Arrow Publicity produced a campaign that is designed to **\\_\\_** audiences between the ages of 18 and 25.", "opts": ["appeal to", "approve of", "point out", "result from"], "ans": 0, "exp": "句意是「Arrow 宣傳公司製作了一個旨在吸引 18 到 25 歲之間受眾的行銷活動。」本題主要測驗動詞與介系詞搭配的片語語意。選項 (A) appeal to 的意思是「吸引、引起⋯⋯的興趣」，放在這裡與後方的受詞「受眾（audiences）」搭配，非常符合行銷活動（campaign）的目的與商業邏輯。選項 (B) approve of 意思是「贊成、同意」，(C) point out 是「指出」，(D) result from 則是「起因於」，這三個選項填入空格後在語意上都顯得突兀，無法合理串聯前後文，因此 (A) 是唯一正確的選擇。", "tags": ["動詞片語"]}, {"id": "國學閱讀綠本 第二回合#Q110", "src": "國學閱讀綠本 第二回合", "no": "Q110", "q": "The company will provide training to new recruits, so neither experience **\\_\\_** a degree is required.", "opts": ["and", "but", "nor", "or"], "ans": 2, "exp": "句意是「公司將會為新進員工提供培訓，因此既不需要經驗也不需要學位。」這題主要考驗相關連接詞（correlative conjunctions）的固定搭配用法。在英文文法中，「neither... nor...」是一個絕對的成對連接詞片語，用來同時否定兩個選項，表示「既不⋯⋯也不⋯⋯」。既然題目句中已經出現了 \"neither\"，空格處就必定要填入 (C) nor 來對等連接 \"experience\"（經驗）與 \"a degree\"（學位）這兩個名詞。選項 (D) or 必須與 either 搭配使用（either... or... 表示「不是⋯⋯就是⋯⋯」），而 (A) and（常搭配 both）與 (B) but（常搭配 not only）在語法結構上都無法與 neither 搭配。", "tags": ["連接詞"]}, {"id": "國學閱讀綠本 第二回合#Q112", "src": "國學閱讀綠本 第二回合", "no": "Q112", "q": "Employees will now be offered the **\\_\\_** of working from home for up to half of their weekly hours.", "opts": ["benefit", "benefited", "beneficial", "benefiting"], "ans": 0, "exp": "句意是「員工現在將享有每週最多一半工時可以居家辦公的福利。」在這題的文法結構中，空格前出現了定冠詞 \"the\"，且其後方緊跟著由介系詞 \"of\" 引導的修飾片語，這明確標示著空格處必須填入一個名詞來作為句中被賦予的事物（保留受詞）。選項 (A) benefit 在此作為名詞，意思是「好處、福利」，完美符合句法結構與職場語意。選項 (B) benefited 是動詞的過去式或過去分詞，(C) beneficial 是形容詞（有益的），(D) benefiting 是動詞現在分詞，這三者的詞性都無法直接放在定冠詞 \"the\" 之後作為獨立名詞使用，因此 (A) 是唯一正確的選擇。", "tags": ["名詞"]}, {"id": "國學閱讀綠本 第二回合#Q113", "src": "國學閱讀綠本 第二回合", "no": "Q113", "q": "Knoll Consulting tries to hire staff **\\_\\_** personal values match the company's.", "opts": ["whom", "which", "whose", "who"], "ans": 2, "exp": "句意是「Knoll 顧問公司試圖聘用個人價值觀與公司相符的員工。」這題主要測驗關係代名詞中「所有格」的用法。在句子中，空格前方的先行詞是 \"staff\"（員工），而空格後方緊接著的是名詞 \"personal values\"（個人價值觀）。這裡要表達的邏輯是「『員工的』個人價值觀」，兩者之間存在著所有權的關係，因此必須填入所有格關係代名詞 whose 來連接兩個子句並修飾前面的 staff。選項 (A) whom 是受格，(B) which 用來指稱事物，(D) who 則是主格，這三個選項都無法表現出「某人的⋯⋯」這種所屬關係，因此 (C) 是唯一正確的選擇。", "tags": ["關係代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q117", "src": "國學閱讀綠本 第二回合", "no": "Q117", "q": "Housing costs in New York are far higher than **\\_\\_** in its neighboring state, New Jersey.", "opts": ["anyone", "other", "that", "those"], "ans": 3, "exp": "句意是「紐約的住房成本遠高於其鄰州紐澤西州」，考驗的是英文比較句型中指示代名詞的用法。為了在同一個句子裡避免重複提及相同的名詞，英文通常會使用代名詞來代替前面已經出現過的事物。在這題當中，比較的對象是兩地的「住房成本（Housing costs）」，因為題幹的 costs 是一個複數名詞，所以空格處必須填入對應的複數代名詞 those 來代替紐澤西州的住房成本。如果今天題目使用的是單數型態（例如 cost），才會選擇 (C) 的 that；至於選項 (A) 的 anyone（任何人）在語意上完全不通，而選項 (B) 的 other 在文法上無法單獨在此作為代名詞進行比較。", "tags": ["指示代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q120", "src": "國學閱讀綠本 第二回合", "no": "Q120", "q": "Having made a reservation, Mr. Quinn and his colleagues were seated immediately **\\_\\_** arriving at the restaurant.", "opts": ["up", "in", "upon", "to"], "ans": 2, "exp": "句意是「由於已經預先訂位，Quinn 先生和他的同事們一抵達餐廳就被立刻安排入座」。這裡考驗的是介系詞的慣用語法。在英文中，「upon + 動名詞 (V-ing)」（或用 on + 動名詞）是一個常見的句型，用來表達「一……就……」或是「在發生某事的當下」的意思。在這個句子裡，「immediately upon arriving」精準地表達了他們抵達的瞬間就隨即入座的狀態。其他的選項 (A) up、(B) in 與 (D) to 在這裡皆無法與 arriving 搭配出表示時間緊接發生的邏輯關聯，因此 (C) 是唯一符合文法與句意的正確解答。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第二回合#Q122", "src": "國學閱讀綠本 第二回合", "no": "Q122", "q": "During her first year as editor-in-chief, Ms. Reed expanded The National Gazette's **\\_\\_** to over 250,000.", "opts": ["Read", "Readers", "reading", "readership"], "ans": 3, "exp": "句意是「在 Reed 女士擔任總編輯的第一年，她將《國家公報》的讀者人數（或讀者群）擴增至超過 25 萬人」，主要考驗的是字彙語意與詞性的搭配。空格前有所有格「The National Gazette's」，因此後面必須接上名詞。雖然選項 (B) 的 readers（讀者們）也是名詞，但在英文慣用語法中，要表達一份刊物的「總讀者人數」或「讀者群」時，會使用集合名詞 readership。搭配動詞 expand（擴大、擴增）與具體達到的數量「250,000」時，使用 expand the readership（擴大讀者群）是最符合新聞出版界的道地表達方式（如果用 readers，通常會寫成 increased the number of readers）。至於選項 (A) read 通常作動詞使用，而 (C) reading 則是表示「閱讀」這個動作的動名詞，兩者在語意與詞性上皆無法用來表示可被量化的受眾規模。", "tags": ["名詞"]}, {"id": "國學閱讀綠本 第二回合#Q125", "src": "國學閱讀綠本 第二回合", "no": "Q125", "q": "The e-mail sent by Mr. Duchene at Laudner Holdings is **\\_\\_** Ms. Coleman was waiting for.", "opts": ["who", "what", "how", "when"], "ans": 1, "exp": "句意是「Laudner 控股公司的 Duchene 先生所寄來的那封電子郵件，正是 Coleman 女士一直在等的東西。」在這個句子中，be 動詞 \"is\" 的後面需要一個名詞性的結構來作為主詞補語，同時後方 \"waiting for\" 的介系詞 \"for\" 也缺少了受詞。選項 (B) what 作為複合關係代名詞，本身就隱含了先行詞，其功能等同於 \"the thing that\"（那個事物），填入後所形成的 \"what Ms. Coleman was waiting for\" 完美解決了前後兩端的文法需求。選項 (A) who 用來指稱人，(C) how 指的是方式，(D) when 則是指時間，這三者在語意上都無法用來代指前面提到的「電子郵件（the e-mail）」。", "tags": ["關係代名詞"]}, {"id": "國學閱讀綠本 第三回合#Q103", "src": "國學閱讀綠本 第三回合", "no": "Q103", "q": "Ms. Conner did not win the Employee of the Year Award because a colleague's sales record was better than \\_\\_\\_.", "opts": ["hers", "herself", "her", "she"], "ans": 0, "exp": "句意是「Conner 沒有贏得年度最佳員工獎，因為一位同事的銷售紀錄比她的還要好。」這題測驗的是比較級結構中的「平行對稱」原則。在 \"better than\" 的前後，比較的對象必須一致：前面是 \"a colleague's sales record\"（同事的銷售紀錄），後面也必須是「她的銷售紀錄」。為了避免重複寫出 \"sales record\"，這裡必須使用所有格代名詞 (A) hers，它就等於 \"her sales record\"。其他選項的詞性皆不符：(B) herself 為反身代名詞；(C) her 若作所有格必須緊接名詞；(D) she 為主格。", "tags": ["代名詞"]}, {"id": "國學閱讀綠本 第三回合#Q108", "src": "國學閱讀綠本 第三回合", "no": "Q108", "q": "A photography exhibition entitled The Awakening is currently \\_\\_\\_ in the Pulsen Gallery's main hall.", "opts": ["expressed", "transformed", "displayed", "reflected"], "ans": 2, "exp": "句意是「一場名為《覺醒》的攝影展目前正在 Pulsen 藝廊的大廳展出。」這題測驗的是動詞單字在被動語態中的語意搭配。主詞是「攝影展 (photography exhibition)」，配合藝廊 (gallery) 的情境，最符合邏輯的動作是「被展出」。因此，填入 (C) displayed 形成 \"is currently displayed\"（目前正被展出）是唯一正確的選擇。其他選項：(A) expressed（被表達）、(B) transformed（被轉換）、(D) reflected（被反映／反射），在語意上都無法與攝影展合理搭配。", "tags": ["字彙", "語態"]}, {"id": "國學閱讀綠本 第三回合#Q109", "src": "國學閱讀綠本 第三回合", "no": "Q109", "q": "The municipal government has promised that it will take \\_\\_\\_ to reduce downtown traffic.", "opts": ["acting", "action", "activation", "activists"], "ans": 1, "exp": "句意是「市政府已承諾將採取行動來減少市中心的交通流量。」這題測驗的是名詞的慣用搭配（collocation）。「採取行動」在英文中的固定用法是 take action，此處的 action 作為不可數名詞使用，前面不加冠詞。其他選項：(A) acting 是動名詞或指「演戲、表演」，無法與 take 搭配成「採取行動」；(C) activation 意為「啟動、活化」，多用於機器或系統的啟用，語意不符；(D) activists 指「（社會運動）行動主義者、激進份子」，是指人的可數名詞，填入後語意變成「政府會帶走激進份子」，不合邏輯。", "tags": ["名詞", "固定搭配"]}];
